package prometheus

import mcp "github.com/daltoniam/switchboard"

var tools = []mcp.ToolDefinition{
	{Name: "prometheus_query", Description: "Run an instant PromQL metric query. Start here for standalone Prometheus metrics without Grafana, datasource registration or a Grafana credential. Use list_targets for scrape diagnostics. Read-only; limited to 100 series and 5000 samples.", Parameters: map[string]string{"query": "PromQL expression", "time": "Optional RFC3339, Unix seconds, now or now-1h evaluation time", "limit": "Maximum series, 1..100 (default 20)"}, Required: []string{"query"}},
	{Name: "prometheus_query_range", Description: "Query Prometheus metric history over a time range using PromQL. Returns columnar timestamps and samples, preserving histogram samples. At most 1000 evaluation points per series and 5000 returned samples across all series.", Parameters: map[string]string{"query": "PromQL expression", "start": "Inclusive RFC3339, Unix seconds or now-1h", "end": "Inclusive RFC3339, Unix seconds or now", "step": "Positive seconds or duration, default chosen for <=1000 points", "limit": "Maximum series, 1..100 (default 20)"}, Required: []string{"query", "start", "end"}},
	{Name: "prometheus_list_alerts", Description: "List active firing or pending Prometheus alerts with labels, annotations and activation time. Use query to investigate why an alert is firing.", Parameters: map[string]string{"state": "Optional firing or pending filter", "limit": "Local result limit 1..100 (default 20); does not limit upstream retrieval"}},
	{Name: "prometheus_list_rules", Description: "List Prometheus alerting and recording rules, expressions, health and rule groups. Preserve groupNextToken for next-page discovery on Prometheus 3.x. Local limits flag incomplete results.", Parameters: map[string]string{"type": "Optional alert or record", "rule_name": "Optional array of exact rule names", "group": "Optional exact rule group", "group_limit": "Rule groups per page, 1..100 (default 20)", "group_next_token": "Optional groupNextToken from previous response", "limit": "Local groups and rules per group cap, 1..100 (default 20)"}},
	{Name: "prometheus_list_targets", Description: "Inspect Prometheus scrape target health, lastError, scrapePool and labels to diagnose down exporters or failed scrapes. Does not follow target URLs or execute probes.", Parameters: map[string]string{"state": "active, dropped or any (default active)", "scrape_pool": "Optional exact scrape pool", "limit": "Local targets per category cap, 1..100 (default 20)"}},
	{Name: "prometheus_search_metrics", Description: "Discover Prometheus metric names using exact PromQL series selectors and join available metadata help, type and unit. Two bounded requests, no per-metric fan-out. Metadata may be absent for recording rules or capped upstream responses.", Parameters: map[string]string{"match": "Optional array of series selectors, e.g. {job=\"api\"}", "start": "Optional timestamp", "end": "Optional timestamp", "limit": "Names and metadata limit, 1..100 (default 20)"}},
	{Name: "prometheus_list_label_values", Description: "List values for a Prometheus label (job, instance or __name__) to build PromQL selectors. Metadata time bounds are approximate and can include series without samples in the interval.", Parameters: map[string]string{"label": "ASCII label name", "match": "Optional array of PromQL series selectors", "start": "Optional timestamp", "end": "Optional timestamp", "limit": "Maximum values, 1..100 (default 20)"}, Required: []string{"label"}},
	{Name: "prometheus_list_series", Description: "List Prometheus time series label sets matching one or more selectors. Returns identifiers, not samples; time bounds are approximate and may include deleted or sample-free series.", Parameters: map[string]string{"match": "Required nonempty array of series selectors", "start": "Optional timestamp", "end": "Optional timestamp", "limit": "Maximum series, 1..100 (default 20)"}, Required: []string{"match"}},
	{Name: "prometheus_server_info", Description: "Get standalone Prometheus build version and runtime health information with two bounded read requests. Does not expose server config, admin operations, filesystem paths or environment variables."},
}
